import test from 'node:test';import assert from 'node:assert/strict';
import {createSignedPayPaymentResult,parsePayPaymentIntent,payPaymentIntentDigest,verifyPayPaymentResult} from '../src/pay-payment.js';
import {createSignedNativeTransfer} from '../src/native-transfer.js';import {walletIdentity} from '../src/crypto.js';
const now=new Date('2026-10-02T14:00:00.000Z'),secret='1'.repeat(64),identity=walletIdentity(secret),recipient=walletIdentity('2'.repeat(64));
const intent={version:'1',intentType:'pay.ynxt.transfer',requestId:'r'.repeat(32),chainId:'ynx_6423-1',productClientId:'ynx-pay-v1',bundleId:'com.ynxweb4.pay',sessionBinding:'a'.repeat(64),invoiceId:'inv_'+ 'b'.repeat(20),centralInvoiceId:'central-001',merchantId:'merchant-001',merchantName:'QA merchant',payoutAddress:recipient.account,amount:3,asset:'YNXT',fee:1,total:4,quoteIssuedAt:now.toISOString(),quoteExpiresAt:new Date(now.getTime()+300000).toISOString(),invoiceSignature:'c'.repeat(128),callback:'ynxpay://payment-result'};
const transfer=createSignedNativeTransfer({accountSecret:secret,to:recipient.account,amount:3,nonce:1});
const sign=(patch={})=>createSignedPayPaymentResult({accountSecret:secret,intent,transferPayload:transfer.payload,issuedAt:now.toISOString(),...patch},now);
test('signed native transfer produces exactly bound Pay V1 result, without minting session or settlement',()=>{const result=sign();assert.equal(result.transactionHash,transfer.hash);assert.equal(result.intentDigest,payPaymentIntentDigest(intent));assert.deepEqual(verifyPayPaymentResult(result,intent,identity.account,now),result);assert.equal(Object.keys(result).length,10);assert(!('token' in result));assert(!('committed' in result));});
test('quote exact five-minute bound and expired/future quote are enforced',()=>{for(const patch of [{quoteExpiresAt:new Date(now.getTime()+300001).toISOString()},{quoteExpiresAt:now.toISOString()},{quoteIssuedAt:new Date(now.getTime()+30001).toISOString()}])assert.throws(()=>parsePayPaymentIntent({...intent,...patch},now));});
test('foreign product, callback, chain, extra field, unsafe or fractional native amount rejected',()=>{for(const patch of [{productClientId:'ynx-finance-v1'},{callback:'ynxwallet://evil'},{chainId:'ynx_other'},{extra:true},{amount:1.5,total:2.5},{amount:Number.MAX_SAFE_INTEGER,total:Number.MAX_SAFE_INTEGER+1}])assert.throws(()=>parsePayPaymentIntent({...intent,...patch},now));});
test('wrong payer, destination, amount or fee cannot produce invoice-bound signature',()=>{assert.throws(()=>sign({accountSecret:'3'.repeat(64)}));for(const input of [{accountSecret:secret,to:walletIdentity('4'.repeat(64)).account,amount:3,nonce:1},{accountSecret:secret,to:recipient.account,amount:4,nonce:1}])assert.throws(()=>sign({transferPayload:createSignedNativeTransfer(input).payload}));const raw=JSON.parse(transfer.payload);assert.throws(()=>sign({transferPayload:JSON.stringify({...raw,fee:2})}));});
test('result signature and every prior payment context remain bound',()=>{const result=sign();for(const patch of [{invoiceId:'inv_'+'e'.repeat(20)},{requestId:'q'.repeat(32)},{transactionHash:'0x'+'0'.repeat(64)},{account:recipient.account},{extra:true},{walletSignature:'0'.repeat(128)}])assert.throws(()=>verifyPayPaymentResult({...result,...patch},intent,identity.account,now));assert.throws(()=>verifyPayPaymentResult(result,{...intent,sessionBinding:'f'.repeat(64)},identity.account,now));});
test('late result timestamps and canonical transfer payload substitution fail closed',()=>{assert.throws(()=>sign({issuedAt:new Date(now.getTime()+300001).toISOString()}));assert.throws(()=>sign({issuedAt:new Date(now.getTime()-1).toISOString()}));assert.throws(()=>sign({transferPayload:transfer.payload+' '}));});
